    FormStaticTextHinweis.foregroundColor(WinAPI::RGB2int(0,0,0));
    FormStaticTextHinweis.fontSize(12);

    FormStaticTextHinweis2.colorScheme(FormColorScheme::RGB);
    FormStaticTextHinweis2.backgroundColor(WinAPI::RGB2int(250,18,43));
    FormStaticTextHinweis2.foregroundColor(WinAPI::RGB2int(0,0,0));
    FormStaticTextHinweis2.fontSize(12);

    FormGridNDXProdIdentProcedureLine12.height(600);
    FormStaticTextHinweis2.text("@NDX:NDXProdIdentCopy1WizardHelpText1");
    FormGridInventTableAll.height(500);

}

