/// <summary>
/// PaffH 02.11.23
/// </summary>
/// <param name = "q">Query</param>
/// <returns>NDXRouteTmp</returns>
public NDXRouteTmp buildFromQuery(Query q)
{
    InventTable locInventTable;
    NDXProdIdentProcedureTable locNDXProdIdentProcedureTable;
    NDXProdIdentProcedureLine1 locNDXProdIdentProcedureLine1;
    Route locRoute;
    NDXRouteTmp locNDXRouteTmp;
    QueryRun qr = new QueryRun(q);
    while (qr.next())
    {
        if (qr.changed(tableNum(InventTable), 1))
        {
            locInventTable = qr.get(tableNum(InventTable), 1);
        }
        if (qr.changed(tableNum(NDXProdIdentProcedureTable), 1))
        {
            locNDXProdIdentProcedureTable = qr.get(tableNum(NDXProdIdentProcedureTable), 1);
        }
        if (qr.changed(tableNum(NDXProdIdentProcedureLine1)))
        {
            locNDXProdIdentProcedureLine1 = qr.get(tableNum(NDXProdIdentProcedureLine1));
        }
        locRoute = Route::findRecId(locNDXProdIdentProcedureLine1.Route);

        locNDXRouteTmp.clear();
        locNDXRouteTmp.ItemId = locInventTable.ItemId;
        locNDXRouteTmp.Release = locNDXProdIdentProcedureLine1.Freigabe;
        locNDXRouteTmp.RouteId = locRoute.RouteId;
        locNDXRouteTmp.RouteName = locRoute.RouteName();
        locNDXRouteTmp.RouteOprId = locRoute.OprId;
        locNDXRouteTmp.OprNum = locRoute.OprNum;
        locNDXRouteTmp.RouteOprName = locRoute.RouteOprName();
        locNDXRouteTmp.Route = locNDXProdIdentProcedureLine1.Route;
        locNDXRouteTmp.RouteVersion = locNDXProdIdentProcedureLine1.RouteVersion;
        locNDXRouteTmp.NDXProdIdentProcedureTable = locNDXProdIdentProcedureLine1.NDXProdIdentProcedureTable;
        locNDXRouteTmp.insert();
    }
    return locNDXRouteTmp;


}

