/// <summary>
/// PaffH 28.10.23
/// </summary>
/// <returns>int</returns>
public int active()
{
    RouteVersion        routeVersion;
    Route               route;
    int64 info1, info2, info3, info4;

    int ret;

    ret = super();

    FormStaticTextHinweis.text('');

    qbrProcedureTable.value(queryValue(InventTable.RecId));
    NDXProdIdentProcedureTable_DS.executeQuery();

    info1 = NDXProdIdentProcedureTable.RecId;
    info2 = NDXProdIdentProcedureLine1.RecId;

    NDXProdIdentProcedureTable locNDXProdIdentProcedureTable = NDXProdIdentProcedureTable::findInventTable(InventTable.RecId);
    //qbrProcedureLine1.value(queryValue(NDXProdIdentProcedureTable.RecId));
    qbrProcedureLine1.value(queryValue(locNDXProdIdentProcedureTable.RecId));
    NDXProdIdentProcedureLine1_DS.executeQuery();

    info3 = NDXProdIdentProcedureTable.RecId;
    info4 = NDXProdIdentProcedureLine1.RecId;

    NDXRouteTmp.setTmpData(element.buildFromQuery(inventTable_ds.query()));
    NDXRouteTmp_ds.executeQuery();

    NDXProdIdentProcedureLine11.initialize();
    NDXProdIdentProcedureLine11.NDXProdIdentProcedureTable = NDXProdIdentProcedureTable.RecId;

    // falls für den Artikel nur ein Ap/Ag vorhanden ist, kann dieser vorbelegt werden
    select count(recId) from routeVersion 
        where routeVersion.ItemId == InventTable.ItemId
        && routeVersion.Active == NoYes::Yes;
    if (routeVersion.RecId == 1)
    {
        select firstonly routeVersion where 
            routeVersion.ItemId == InventTable.ItemId
            && routeVersion.Active == NoYes::Yes;
        select firstonly route where route.RouteId == routeVersion.RouteId;

        NDXProdIdentProcedureLine11.RouteVersion = routeVersion.RecId;
        NDXProdIdentProcedureLine11.Route = route.RecId;

        // AP einfach vorhanden ?
        select count(recid) from route
            where route.RouteId         == routeVersion.RouteId
            &&  route.OprPriority   == RouteOprPriority::Primary;
        if (route.RecId == 1)
        {
            select firstonly route
                where route.RouteId == routeVersion.RouteId
                &&  route.OprPriority   == RouteOprPriority::Primary;

            NDXProdIdentProcedureLine11.Route = route.RecId;
            NDXProdIdentProcedureLine11_DS.setHinweis();
        }
    }

    return ret;
}

