void RefRecIdRoute_modified_Post()
{
    if (NDXProdIdentProcedureLine11.Route)
    {
        if (!sysWizard.isNextEnabled())
        {
            sysWizard.nextEnabled(true, sysWizard.curTab(), false);
        }
    }
    else
    {
        if (sysWizard.isNextEnabled())
        {
            sysWizard.nextEnabled(false, sysWizard.curTab(), false);
        }

    }

}

/// <summary>
/// PaffH 28.10.23
/// </summary>
void setHinweis()
{
    NDXProdIdentProcedureLine1 lNDXProdIdentProcedureLine1;
    NDXProdIdentProcedureLine2 lNDXProdIdentProcedureLine2;

    select firstonly lNDXProdIdentProcedureLine1
        where lNDXProdIdentProcedureLine1.NDXProdIdentProcedureTable == NDXRouteTmp.NDXProdIdentProcedureTable
        && lNDXProdIdentProcedureLine1.Route == NDXRouteTmp.Route
        && lNDXProdIdentProcedureLine1.RouteVersion == NDXRouteTmp.RouteVersion;
    if (lNDXProdIdentProcedureLine1)
    {
        FormStaticTextHinweis.foregroundColor(WinAPI::rgb2int(255,247,17));      // gelb
        FormStaticTextHinweis.backgroundColor(WinAPI::rgb2int(255,14,10));       // rot
        // Wurden bereits Kennzeichnungsverfahren zugeordnet?
        select firstOnly lNDXProdIdentProcedureLine2
            where        lNDXProdIdentProcedureLine2.NDXProdIdentProcedureLine1 == lNDXProdIdentProcedureLine1.RecId;
        if (lNDXProdIdentProcedureLine2)
        {
            FormStaticTextHinweis.text("@NDX:NDXProdIdentCopy1WizardHelpText2");
        }
        else
        {
            FormStaticTextHinweis.text("@NDX:NDXProdIdentCopy1WizardHelpText3");
        }
    }
    else
    {
        FormStaticTextHinweis.foregroundColor(WinAPI::rgb2int(0,0,0));          // schwarz
        FormStaticTextHinweis.backgroundColor(WinAPI::rgb2int(229,229,229));    // hellgrau
        FormStaticTextHinweis.text("@NDX:NDXProdIdentCopy1WizardHelpText4");
    }
}

