/// <summary>
/// PaffH 31.10.23
/// </summary>
public void modified()
{
    super();
    RouteVersion locRouteVersion = RouteVersion::findRecId(NDXProdIdentProcedureLine11.RouteVersion);
    Route locRoute = Route::findRecId(NDXProdIdentProcedureLine11.Route);
    if (locRouteVersion.RouteId != locRoute.RouteId)
    {
        select firstonly locRoute where locRoute.RouteId == locRouteVersion.RouteId;
        NDXProdIdentProcedureLine11.Route = locRoute.RecId;
        NDXProdIdentProcedureLine11.write();
    }
}

