/// <summary>
/// PaffH 30.10.23
/// </summary>
/// <returns>int</returns>
public int active()
{
    int ret;
    int64 info1, info2, info3, info4, info5, info6;

    ret = super();

    if (InventTableAll_DS.anyMarked())
    {
        info1 = InventTable.RecId;
        qbrInventTable.value(queryValue(InventTableAll.RecId));
        InventTable_DS.executeQuery();
        info2 = InventTable.RecId;
        NDXProdIdentProcedureTable locNDXProdIdentProcedureTable = NDXProdIdentProcedureTable::findInventTable(InventTableAll.RecId);
        info3 = NDXProdIdentProcedureTable.RecId;
        qbrProcedureTable.value(queryValue(InventTable.RecId));
        NDXProdIdentProcedureTable_ds.executeQuery();
        info4 = NDXProdIdentProcedureTable.RecId;
        info5 = NDXProdIdentProcedureLine1.RecId;
        //qbrProcedureLine1.value(queryValue(NDXProdIdentProcedureTable.RecId));
        qbrProcedureLine1.value(queryValue(locNDXProdIdentProcedureTable.RecId));
        NDXProdIdentProcedureLine1_DS.executeQuery();
        info6 = NDXProdIdentProcedureLine1.RecId;

        NDXRouteTmp.setTmpData(element.buildFromQuery(inventTable_ds.query()));
        NDXRouteTmp_ds.executeQuery();

        if (InventTableAll.RecId!= sysWizard.parmInventTable().RecId)
        {
            FormStaticTextHinweis2.text(strfmt("@NDX:NDXProdIdentCopy1WizardHelpText5", sysWizard.parmInventTable().ItemId));
            FormStaticTextHinweis2.visible(true);
        }
        else
        {
            FormStaticTextHinweis2.text('');
            FormStaticTextHinweis2.visible(false);
        }
    }
    return ret;
}

